CREATE TABLE execution_grants(id TEXT NOT NULL,workspace_id TEXT NOT NULL,version INTEGER NOT NULL,issuer_id TEXT NOT NULL,principal_id TEXT NOT NULL,parent_id TEXT,parent_version INTEGER,action TEXT NOT NULL,action_version INTEGER NOT NULL,target TEXT NOT NULL,beneficiary_id TEXT NOT NULL,connection_id TEXT NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,max_uses INTEGER NOT NULL CHECK(max_uses>0),conditions_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id,version));
CREATE TABLE execution_grant_revocations(workspace_id TEXT NOT NULL,grant_id TEXT NOT NULL,version INTEGER NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,grant_id,version));
CREATE TABLE execution_plans(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,work_revision INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,actor_id TEXT NOT NULL,steps_json TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'proposed',idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,idempotency_key));
CREATE TABLE execution_decisions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,plan_id TEXT NOT NULL,operation_id TEXT,actor_id TEXT NOT NULL,grant_id TEXT,grant_version INTEGER,allowed INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE execution_operations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,plan_id TEXT NOT NULL,step_json TEXT NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,fence INTEGER NOT NULL DEFAULT 0,resource TEXT NOT NULL,actor_id TEXT NOT NULL,cancel_requested INTEGER NOT NULL DEFAULT 0,lease_until TEXT,due_at TEXT,parent_id TEXT,created_at TEXT NOT NULL,UNIQUE(plan_id,parent_id,resource));
CREATE TABLE execution_fences(workspace_id TEXT NOT NULL,resource TEXT NOT NULL,operation_id TEXT NOT NULL,fence INTEGER NOT NULL,PRIMARY KEY(workspace_id,resource));
CREATE TABLE execution_attempts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,operation_id TEXT NOT NULL,fence INTEGER NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,elapsed_ms INTEGER,charge_status TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE execution_receipts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,operation_id TEXT NOT NULL,attempt_id TEXT NOT NULL,state TEXT NOT NULL,provider_status INTEGER,created_at TEXT NOT NULL);
CREATE TABLE execution_verifications(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,operation_id TEXT NOT NULL,verifier_version INTEGER NOT NULL,action_version INTEGER NOT NULL,target TEXT NOT NULL,beneficiary_id TEXT NOT NULL,state TEXT NOT NULL,evidence_json TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE INDEX execution_due ON execution_operations(state,due_at);
CREATE TRIGGER execution_grants_immutable BEFORE UPDATE ON execution_grants BEGIN SELECT RAISE(ABORT,'immutable grant'); END;
CREATE TRIGGER execution_decisions_immutable BEFORE UPDATE ON execution_decisions BEGIN SELECT RAISE(ABORT,'immutable decision'); END;
